  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Fills water tiles up to the given distance from the source using BFS expansion.
   * Algorithm:
   *   1. If distance == 0, do nothing.
   *   2. If this is the first fill (prevFilledDistance == null), call fillBeginTile() to mark source as filled.
   *   3. Perform BFS from the source, expanding outward up to the given distance.
   *   4. For each pipe encountered, check connection compatibility with neighboring pipes.
   *      Water may move from one pipe to an adjacent pipe only when the outgoing direction of one pipe matches the opposite direction of the neighboring pipe.
   *   5. Mark reachable pipes as filled.
   *   6. Update prevFilledDistance and prevFilledTiles.
   * Related Features: sourceCell, filledTiles, prevFilledDistance, prevFilledTiles fields
   * Related Classes: TerminationCell, Coordinate, Pipe, Direction, FillableCell
   * Input: distance : int - the expansion distance from source
   * Output: void
   * Pre-condition: distance >= 0
   * Post-condition: All pipes within the given distance that are properly connected are marked as filled.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    if (distance == 0) {
        return;
    }
    
    if (getPrevFilledDistance() == null) {
        fillBeginTile();
    }
    
    // BFS from source
    java.util.Queue<Coordinate> queue = new java.util.LinkedList<>();
    java.util.Set<Coordinate> visited = new java.util.HashSet<>();
    
    Coordinate sourceCoord = getSourceCell().getCoordinate();
    queue.add(sourceCoord);
    visited.add(sourceCoord);
    
    int currentDistance = 0;
    
    while (!queue.isEmpty() && currentDistance < distance) {
        int size = queue.size();
        for (int i = 0; i < size; i++) {
            Coordinate current = queue.poll();
            Cell currentCell = getCell()[current.getRow()][current.getCol()];
            
            if (currentCell instanceof FillableCell) {
                FillableCell fillableCell = (FillableCell) currentCell;
                if (fillableCell.getPipe() != null) {
                    Pipe pipe = fillableCell.getPipe();
                    // Mark this cell as filled
                    if (!getFilledTiles().contains(current)) {
                        getFilledTiles().add(current);
                    }
                    
                    // Check neighbors
                    for (Direction dir : pipe.getOpenDirections()) {
                        Coordinate neighbor = getNeighbor(current, dir);
                        if (neighbor != null && !visited.contains(neighbor)) {
                            Cell neighborCell = getCell()[neighbor.getRow()][neighbor.getCol()];
                            if (neighborCell instanceof FillableCell) {
                                FillableCell neighborFillable = (FillableCell) neighborCell;
                                if (neighborFillable.getPipe() != null) {
                                    Pipe neighborPipe = neighborFillable.getPipe();
                                    Direction oppositeDir = getOppositeDirection(dir);
                                    if (neighborPipe.getOpenDirections().contains(oppositeDir)) {
                                        visited.add(neighbor);
                                        queue.add(neighbor);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        currentDistance++;
    }
    
    setPrevFilledDistance(distance);
    setPrevFilledTiles(getFilledTiles().size());
  }

